/* Column layout */
column-set {
    display: flex;
    flex-wrap: wrap;
    gap: 2.3rem;
    align-items: flex-start; /* ensures all columns start at the same top line */
    position: relative;
    top: 0.3rem;  /* moves the block upward */
    margin-right: 2rem;
    padding-left: 20px;
}

/* Column widths (based on 12-column span) */
column-unit[slot="0"] { flex: 0 0 40%; }
column-unit[slot="1"] { flex: 0 0 25%; }
column-unit[slot="2"] { flex: 0 0 25%; }

/* Make columns stack on small screens */
@media screen and (max-width: 768px) {
    column-set {
        flex-direction: column;
    }
    column-unit {
        flex: 0 0 100%;
    }
}

/* --- Unified text classes --- */

/* Headline for all titles */
h2 {
    font-size: 1.35rem;      /* unified size */
    line-height: 1.6;     /* consistent spacing */
    color: #ffffff;
    margin: 0 0 0.3rem 0; /* minimal spacing below */
}

/* Paragraphs */
p {
    font-size: 1.05rem;      /* unified size */
    line-height: 1.30;     /* consistent spacing */
    color: #d1d1d1;
    margin: 0 0 0.5rem 0; /* minimal spacing between lines */
}

/* Minimal address styling */


.address-wrapper p {
    line-height: 0.6;     /* consistent with other text */
    font-size: 1.05rem;      /* match main text */
    top: 0rem;
    margin-top: 9.5px;
    color: #d1d1d1;
}

.address-wrapper a {
    font-size: 1.0rem;      /* match main text */
    color: #d1d1d1;
    text-decoration: none;
    position: relative;
    display: inline-block;
}

/* Animated underline for links */
.address-wrapper a::after {
    content: "";
    position: absolute;
    left: 0;
    bottom: -0.3rem;      /* minimal spacing below text */
    width: 100%;
    height: 1.5px;
    background-color: currentColor;
    transform: scaleX(0);
    transform-origin: left;
    transition: transform 0.3s ease;
}

.address-wrapper a:hover {
    color: white;
}

.address-wrapper a:hover::after {
    transform: scaleX(1);
}

/* Images and media-items responsive */
img, media-item {
    width: 100%;
    height: auto;
    display: block;
}

/* About text paragraphs */
.about-text p {
    position: relative;
    top: .0rem;
    text-align: justify;
    text-justify: inter-word;
    hyphens: auto;
}

 @media (min-width: 1490px) {
     .address-wrapper p {
    line-height: 0.6;     /* consistent with other text */
